mapper.select:
SELECT m.message_id AS messageId, m.conversation_id AS conversationId, m.sender_id AS senderId, u.nick_name AS senderName, u.avatar AS senderAvatar, m.message_type AS messageType, m.content, m.create_time AS createTime, m.status, m.reply_to_message_id AS replyToMessageId FROM message m LEFT JOIN user_info u ON m.sender_id = u.user_id WHERE m.conversation_id = #{conversationId}
AND m.message_id < #{lastMessageId}
ORDER BY m.create_time DESC LIMIT #{size}
